import json
TOOLS = {"get_cluster_alerts": {
    "description": "클러스터의 CRITICAL/WARNING 알림 요약(읽기 전용)",
    "inputSchema": {"type": "object", "properties": {"cluster_id": {"type": "string"}},
                    "required": ["cluster_id"]}}}
def get_cluster_alerts(cluster_id):
    return {"cluster_id": cluster_id, "critical": 1, "warning": 3}

def handle(msg):
    if msg["method"] == "tools/list":
        result = {"tools": [{"name": n, **t} for n, t in TOOLS.items()]}
    elif msg["method"] == "tools/call":
        args = msg["params"]["arguments"]
        if "cluster_id" not in args:
            result = {"isError": True, "content": [{"type": "text", "text": "cluster_id 가 필요합니다"}]}
        else:
            text = json.dumps(get_cluster_alerts(**args), ensure_ascii=False)
            result = {"content": [{"type": "text", "text": text}]}
    return {"jsonrpc": "2.0", "id": msg["id"], "result": result}

print([t["name"] for t in handle({"jsonrpc": "2.0", "id": 1, "method": "tools/list"})["result"]["tools"]])
call = {"name": "get_cluster_alerts", "arguments": {"cluster_id": "PROD01"}}
print(handle({"jsonrpc": "2.0", "id": 2, "method": "tools/call", "params": call})["result"]["content"][0]["text"])
bad = {"name": "get_cluster_alerts", "arguments": {}}
print(handle({"jsonrpc": "2.0", "id": 3, "method": "tools/call", "params": bad})["result"])

