def final(rca): return round(rca["confidence"] + rca["robustness"], 2)
def reflect(a, b):
    if a["root_cause"] == b["root_cause"]:
        return a["root_cause"], "두 모델 합의", max(final(a), final(b))
    win = a if final(a) >= final(b) else b
    return win["root_cause"], "점수로 판정", final(win)
a = {"root_cause": "방화벽 정책 변경", "confidence": 0.70, "robustness": +0.08}
b = {"root_cause": "NameNode 힙 부족", "confidence": 0.75, "robustness": -0.06}
print(final(a), final(b), reflect(a, b))
print(reflect(a, dict(b, root_cause="방화벽 정책 변경")))

